const output = $json.output || $json;

let parsedType = 'unknown';
let parsedConfidence = 0.5;
let parsedReason = '';

if (typeof output === 'object' && output !== null) {
  parsedType = (output.type || 'unknown').toLowerCase();
  parsedConfidence = typeof output.confidence === 'number' ? output.confidence : parseFloat(output.confidence) || 0.5;
  parsedReason = output.reason || '';
}

return {
  json: {
    type: parsedType,
    confidence: parsedConfidence,
    reason: parsedReason
  }
};
